INSERT INTO `image_metadata` (`meta_id`, `image_id`, `alt_text`, `title`, `description`, `caption`) VALUES
(745, 737, 'OBLIVOR L-707 20000mAh Power Bank with 65W Fast Charging – High-Speed PD Power Bank for Smartphones, Tablets, and USB Devices', 'L-707 Oblivor Power Bank', 'Introducing the OBLIVOR L-707 Power Bank, designed for high-speed, portable charging wherever you go. With a 20,000mAh high-density Li-Polymer battery and 65W fast output, it delivers powerful, efficient charging for smartphones, tablets, and other USB devices. Its premium smooth-finish body, PD, USB, and built-in cable support, and smart overheat protection ensure safe, flexible performance in a sleek, travel-friendly design.', 'OBLIVOR L-707 20000mAh power bank featuring 65W fast charging, PD and USB support, built-in cable, Li-Polymer battery, and premium smooth-finish portable design for smartphones and tablets'),
(746, 738, 'L-712 Magna Power Bank Front View', 'L-712 Magna Power Bank Front', 'High-quality front view showing compact design of L-712 Magna Power Bank in Gold color.', 'Front view of L-712 Magna Power Bank in Gold'),
