INSERT INTO `product_seo` (`seo_id`, `product_id`, `seo_title`, `seo_description`, `focus_keyword`) VALUES
(1, 1, 'Audionic Airbud 590 Wireless Earbuds', 'Audionic Airbud 590 Wireless Earbuds Price In Pakistan 2024', 'Buy Audionic Airbud 590 Wireless Earbuds in Pakistan with ENC, IPX4 water resistance, and up to 6 hours of playtime. Perfect for Android, iOS, and Windows devices.'),
(2, 2, 'Audionic Wireless Airbuds 425', 'Audionic Wireless Airbuds 425 Price In Pakistan 2025', 'Buy Audionic Wireless Airbuds 425 in Pakistan with ENC noise cancellation, IPX4 water resistance, Bluetooth 5.3, and USB-C charging. Ideal for music and calls in 2025!'),
